const e=[{id:"conj-und",category:"conjunction",de:"und",en:["and"],hi:["और"],hiTranslit:"aur",ipa:"ʊnt",deva:"उन्ट्",level:"A1",theme:"logic",illustration:"conj-und",type:"coordinating",verbPosition:"zero",examples:[{de:[{t:"Ich",g:0},{t:"koche",g:1},{t:","},{t:"und",g:2},{t:"du",g:3},{t:"deckst",g:4},{t:"den Tisch",g:5}],en:[{t:"I",g:0},{t:"cook",g:1},{t:","},{t:"and",g:2},{t:"you",g:3},{t:"set",g:4},{t:"the table",g:5}],hi:[{t:"मैं",g:0},{t:"खाना बनाता हूँ",g:1},{t:","},{t:"और",g:2},{t:"तुम",g:3},{t:"मेज़",g:5},{t:"लगाते हो",g:4}],hiTranslit:"main khaana banaata hoon, aur tum mez lagaate ho",note:'"und" links two independent clauses without occupying a position of its own — the verb stays second in each clause it joins, in German, English, and Hindi alike.'}]},{id:"conj-oder",category:"conjunction",de:"oder",en:["or"],hi:["या"],hiTranslit:"ya",ipa:"ˈoːdɐ",deva:"ओडा",level:"A1",theme:"logic",illustration:"conj-oder",type:"coordinating",verbPosition:"zero",examples:[{de:[{t:"Möchtest du",g:0},{t:"Tee",g:1},{t:"oder",g:2},{t:"Kaffee",g:3},{t:"?"}],en:[{t:"Do you want",g:0},{t:"tea",g:1},{t:"or",g:2},{t:"coffee",g:3},{t:"?"}],hi:[{t:"तुम्हें",g:0},{t:"चाय",g:1},{t:"चाहिए",g:0},{t:"या",g:2},{t:"कॉफ़ी",g:3},{t:"?"}],hiTranslit:"tumhein chai chahiye ya coffee?",note:'"oder" simply offers a choice between two nouns — it never forces the verb to move, unlike the subordinators later in this set.'}]},{id:"conj-aber",category:"conjunction",de:"aber",en:["but"],hi:["लेकिन","पर"],hiTranslit:"lekin / par",ipa:"ˈaːbɐ",deva:"आबा",level:"A1",theme:"logic",illustration:"conj-aber",type:"coordinating",verbPosition:"zero",examples:[{de:[{t:"Ich",g:0},{t:"möchte",g:1},{t:"Tee",g:2},{t:","},{t:"aber",g:3},{t:"ich",g:0},{t:"trinke",g:4},{t:"Kaffee",g:5}],en:[{t:"I",g:0},{t:"want",g:1},{t:"tea",g:2},{t:","},{t:"but",g:3},{t:"I",g:0},{t:"drink",g:4},{t:"coffee",g:5}],hi:[{t:"मैं",g:0},{t:"चाय",g:2},{t:"चाहता हूँ",g:1},{t:","},{t:"लेकिन",g:3},{t:"मैं",g:0},{t:"कॉफ़ी",g:5},{t:"पीता हूँ",g:4}],hiTranslit:"main chai chaahta hoon, lekin main coffee peeta hoon",note:'"aber" sits between the two clauses it contrasts but claims no position of its own — verb-second holds on both sides, unlike the true subordinators that follow.'}]},{id:"conj-denn",category:"conjunction",de:"denn",en:["because","for"],hi:["क्योंकि"],hiTranslit:"kyonki",ipa:"dɛn",deva:"डेन्",level:"A2",theme:"logic",illustration:"conj-denn",type:"coordinating",verbPosition:"zero",notes:'Contrast with weil: both mean "because", but denn leaves the verb in position 2 while weil sends it to the very end of its clause — same meaning, opposite word order.',examples:[{de:[{t:"Ich",g:0},{t:"bleibe",g:1},{t:"zu Hause",g:2},{t:","},{t:"denn",g:3},{t:"ich",g:4},{t:"bin",g:5},{t:"krank",g:6}],en:[{t:"I",g:0},{t:"am staying",g:1},{t:"at home",g:2},{t:","},{t:"for",g:3},{t:"I",g:4},{t:"am",g:5},{t:"sick",g:6}],hi:[{t:"मैं",g:0},{t:"घर पर",g:2},{t:"रहता हूँ",g:1},{t:","},{t:"क्योंकि",g:3},{t:"मैं",g:4},{t:"बीमार",g:6},{t:"हूँ",g:5}],hiTranslit:"main ghar par rehta hoon, kyonki main beemaar hoon",note:'"denn" gives a reason but — unlike "weil" — takes no clause position, so "bin" stays second right after "ich"; compare "weil ich krank bin", where the same reason sends the verb to the very end.'}]},{id:"conj-sondern",category:"conjunction",de:"sondern",en:["but rather","but instead"],hi:["बल्कि"],hiTranslit:"balki",ipa:"ˈzɔndɐn",deva:"ज़ॉन्डन्",level:"A2",theme:"logic",illustration:"conj-sondern",type:"coordinating",verbPosition:"zero",notes:'Only usable after an explicit negation (nicht/kein) in the first clause — it rejects a stated alternative rather than simply adding new information, which is what "aber" does.',examples:[{de:[{t:"Ich",g:0},{t:"trinke",g:1},{t:"keinen Kaffee",g:2},{t:","},{t:"sondern",g:3},{t:"Tee",g:4}],en:[{t:"I",g:0},{t:"do not drink",g:1},{t:"coffee",g:2},{t:","},{t:"but rather",g:3},{t:"tea",g:4}],hi:[{t:"मैं",g:0},{t:"कॉफ़ी",g:2},{t:"नहीं पीता",g:1},{t:","},{t:"बल्कि",g:3},{t:"चाय",g:4}],hiTranslit:"main coffee nahin peeta, balki chai",note:'"sondern" replaces a rejected alternative after a negative clause; like the other coordinators it takes no position, so German can drop the repeated verb after it exactly as English and Hindi do here.'}]},{id:"conj-entweder",category:"conjunction",de:"entweder",en:["either... or"],hi:["या तो... या"],hiTranslit:"ya to... ya",ipa:"ɛntˈveːdɐ",deva:"एन्ट्वेडा",level:"A2",theme:"logic",illustration:"conj-entweder",type:"two-part",verbPosition:"inversion",secondPart:"oder",notes:'"entweder" occupies position 1 of its own clause, so the verb comes right after it, before the subject — inversion, like an adverbial connector. But "oder" is a plain coordinator with no position of its own, so the second clause keeps normal subject-verb order — see the example note.',examples:[{de:[{t:"Entweder",g:0},{t:"gehe",g:1},{t:"ich",g:2},{t:"ins Kino",g:3},{t:","},{t:"oder",g:4},{t:"ich",g:2},{t:"bleibe",g:5},{t:"zu Hause",g:6}],en:[{t:"Either",g:0},{t:"I",g:2},{t:"go",g:1},{t:"to the cinema",g:3},{t:","},{t:"or",g:4},{t:"I",g:2},{t:"stay",g:5},{t:"home",g:6}],hi:[{t:"या तो",g:0},{t:"मैं",g:2},{t:"सिनेमा",g:3},{t:"जाता हूँ",g:1},{t:","},{t:"या",g:4},{t:"मैं",g:2},{t:"घर पर",g:6},{t:"रहता हूँ",g:5}],hiTranslit:"ya to main cinema jaata hoon, ya main ghar par rehta hoon",note:'"entweder" occupies position 1, so "gehe" comes right after it, before "ich" — inversion; but "oder" is a plain coordinator with no clause position, so the second clause keeps normal subject-verb order ("ich bleibe"), not inversion.'}]},{id:"conj-weder",category:"conjunction",de:"weder",en:["neither... nor"],hi:["न... न"],hiTranslit:"na... na",ipa:"ˈveːdɐ",deva:"वेडा",level:"A2",theme:"logic",illustration:"conj-weder",type:"two-part",verbPosition:"zero",secondPart:"noch",examples:[{de:[{t:"Ich",g:0},{t:"mag",g:1},{t:"weder",g:2},{t:"Kaffee",g:3},{t:"noch",g:4},{t:"Tee",g:5}],en:[{t:"I",g:0},{t:"like",g:1},{t:"neither",g:2},{t:"coffee",g:3},{t:"nor",g:4},{t:"tea",g:5}],hi:[{t:"मुझे",g:0},{t:"न",g:2},{t:"कॉफ़ी",g:3},{t:"पसंद है",g:1},{t:","},{t:"न",g:4},{t:"चाय",g:5}],hiTranslit:"mujhe na coffee pasand hai, na chai",note:'"weder... noch" negates every item it links; joining two objects inside one clause leaves only a single verb to place, and the correlative pair still claims no position of its own.'}]},{id:"conj-sowohl",category:"conjunction",de:"sowohl",en:["both... and"],hi:["दोनों... और"],hiTranslit:"donon... aur",ipa:"zoːˈvoːl",deva:"ज़ोवोल्",level:"B1",theme:"logic",illustration:"conj-sowohl",type:"two-part",verbPosition:"zero",secondPart:"als auch",examples:[{de:[{t:"Sie",g:0},{t:"spricht",g:1},{t:"sowohl",g:2},{t:"Deutsch",g:3},{t:"als auch",g:4},{t:"Englisch",g:5}],en:[{t:"She",g:0},{t:"speaks",g:1},{t:"both",g:2},{t:"German",g:3},{t:"and",g:4},{t:"English",g:5}],hi:[{t:"वह",g:0},{t:"जर्मन",g:3},{t:"और",g:4},{t:"अंग्रेज़ी",g:5},{t:"दोनों",g:2},{t:"बोलती है",g:1}],hiTranslit:"vah German aur angrezi donon bolti hai",note:'"sowohl... als auch" links two objects of equal weight in a single clause; Hindi places "दोनों" after both items instead of a marker before the first, as German does.'}]},{id:"conj-nicht-nur",category:"conjunction",de:"nicht nur",en:["not only... but also"],hi:["न केवल... बल्कि... भी"],hiTranslit:"na keval... balki... bhi",ipa:"nɪçt nuːɐ̯",deva:"निख़्ट् नूअ",level:"B1",theme:"logic",illustration:"conj-nicht-nur",type:"two-part",verbPosition:"inversion",secondPart:"sondern auch",notes:'"nicht nur" occupies position 1 of its own clause, so the verb comes right after it, before the subject — inversion, like an adverbial connector. But "sondern" is a plain coordinator with no position of its own, so the second clause keeps normal subject-verb order — see the example note.',examples:[{de:[{t:"Nicht nur",g:0},{t:"ist",g:1},{t:"er",g:2},{t:"klug",g:3},{t:","},{t:"sondern",g:4},{t:"er",g:2},{t:"ist",g:1},{t:"auch",g:5},{t:"freundlich",g:6}],en:[{t:"Not only",g:0},{t:"is",g:1},{t:"he",g:2},{t:"smart",g:3},{t:","},{t:"but",g:4},{t:"he",g:2},{t:"is",g:1},{t:"also",g:5},{t:"friendly",g:6}],hi:[{t:"वह",g:2},{t:"न केवल",g:0},{t:"होशियार",g:3},{t:"है",g:1},{t:","},{t:"बल्कि",g:4},{t:"दोस्ताना",g:6},{t:"भी",g:5},{t:"है",g:1}],hiTranslit:"vah na keval hoshiyaar hai, balki dostaana bhi hai",note:'"nicht nur" occupies position 1, so "ist" comes right after it, before "er" — inversion; but "sondern" is a plain coordinator with no clause position, so the second clause keeps normal subject-verb order ("er ist"), not inversion. Hindi marks the "also" sense with a separate word "भी" instead.'}]},{id:"conj-zwar",category:"conjunction",de:"zwar",en:["admittedly","it is true that"],hi:["हालांकि","यह सच है कि"],hiTranslit:"haalaanki / yah sach hai ki",ipa:"tsvaːɐ̯",deva:"त्स्वाअ",level:"B1",theme:"logic",illustration:"conj-zwar",type:"two-part",verbPosition:"inversion",secondPart:"aber",notes:'"zwar" occupies position 1 of its own clause, so the verb comes right after it, before the subject — inversion, like an adverbial connector. But "aber" is a plain coordinator with no position of its own, so the second clause keeps normal subject-verb order — see the example note.',examples:[{de:[{t:"Zwar",g:0},{t:"ist",g:1},{t:"das Auto",g:2},{t:"teuer",g:3},{t:","},{t:"aber",g:4},{t:"es",g:5},{t:"ist",g:1},{t:"sehr",g:6},{t:"gut",g:7}],en:[{t:"Admittedly",g:0},{t:"the car",g:2},{t:"is",g:1},{t:"expensive",g:3},{t:","},{t:"but",g:4},{t:"it",g:5},{t:"is",g:1},{t:"very",g:6},{t:"good",g:7}],hi:[{t:"हालांकि",g:0},{t:"गाड़ी",g:2},{t:"महँगी",g:3},{t:"है",g:1},{t:","},{t:"लेकिन",g:4},{t:"यह",g:5},{t:"बहुत",g:6},{t:"अच्छी",g:7},{t:"है",g:1}],hiTranslit:"haalaanki gaadi mehngi hai, lekin yah bahut achchi hai",note:'"zwar" occupies position 1, so "ist" comes right after it, before "das Auto" — inversion; but "aber" is a plain coordinator with no clause position, so the second clause keeps normal subject-verb order ("es ist"), not inversion.'}]},{id:"conj-je",category:"conjunction",de:"je",en:["the... the"],hi:["जितना... उतना"],hiTranslit:"jitna... utna",ipa:"jeː",deva:"ये",level:"B1",theme:"logic",illustration:"conj-je",type:"two-part",verbPosition:"final",secondPart:"desto",notes:'"je" itself sends the verb to the end of its clause like a true subordinator — hence verbPosition "final" here, unlike every other two-part pair in this set. Its partner "desto" then behaves like an adverbial connector and inverts the verb before its subject instead — one correlative pair, two different word-order shifts; see the example note.',examples:[{de:[{t:"Je mehr",g:0},{t:"du",g:1},{t:"übst",g:2},{t:","},{t:"desto besser",g:3},{t:"wirst",g:4},{t:"du",g:1}],en:[{t:"The more",g:0},{t:"you",g:1},{t:"practice",g:2},{t:","},{t:"the better",g:3},{t:"you",g:1},{t:"become",g:4}],hi:[{t:"जितना ज़्यादा",g:0},{t:"तुम",g:1},{t:"अभ्यास करते हो",g:2},{t:","},{t:"उतना ही बेहतर",g:3},{t:"तुम",g:1},{t:"बनते हो",g:4}],hiTranslit:"jitna zyaada tum abhyaas karte ho, utna hi behtar tum banate ho",note:'"je" pushes "übst" to the end of its clause like any subordinator, then "desto" inverts "wirst" before its subject like an adverbial connector — one correlative pair, two different word-order shifts.'}]},{id:"conj-teils",category:"conjunction",de:"teils",en:["partly... partly"],hi:["कुछ हद तक... कुछ हद तक"],hiTranslit:"kuch had tak... kuch had tak",ipa:"taɪls",deva:"टाइल्स्",level:"B1",theme:"logic",illustration:"conj-teils",type:"two-part",verbPosition:"inversion",secondPart:"teils",notes:'"teils" fronts its own clause each time it is used, so both halves trigger inversion — unlike "sowohl...als auch" and "weder...noch", which link two items inside a single clause and leave the verb in position two.',examples:[{de:[{t:"Teils",g:0},{t:"regnete",g:1},{t:"es",g:2},{t:","},{t:"teils",g:3},{t:"schien",g:4},{t:"die Sonne",g:5}],en:[{t:"Partly",g:0},{t:"it",g:2},{t:"rained",g:1},{t:","},{t:"partly",g:3},{t:"the sun",g:5},{t:"shone",g:4}],hi:[{t:"कुछ हद तक",g:0},{t:"बारिश",g:2},{t:"हुई",g:1},{t:","},{t:"कुछ हद तक",g:3},{t:"धूप",g:5},{t:"निकली",g:4}],hiTranslit:"kuch had tak baarish hui, kuch had tak dhoop nikli",note:'"teils" fronts each clause, so "regnete" comes right after the first "teils" (before "es") and "schien" comes right after the second "teils" (before "die Sonne") — inversion in both halves, not the verb-second order "sowohl...als auch" and "weder...noch" leave untouched.'}]},{id:"conj-einerseits",category:"conjunction",de:"einerseits",en:["on the one hand... on the other hand"],hi:["एक तरफ़... दूसरी तरफ़"],hiTranslit:"ek taraf... dusri taraf",ipa:"ˈaɪnɐzaɪts",deva:"आइनज़ाइट्स्",level:"B1",theme:"logic",illustration:"conj-einerseits",type:"two-part",verbPosition:"inversion",secondPart:"andererseits",notes:'Both halves front their own clause and each triggers inversion on its own — "einerseits" forces "möchte" before "ich", and "andererseits" forces "fehlt" before "mir das Geld" — a genuine adverbial-connector pattern, unlike the object-linking pairs "sowohl...als auch" and "weder...noch", which leave the verb in position two.',examples:[{de:[{t:"Einerseits",g:0},{t:"möchte",g:1},{t:"ich",g:2},{t:"reisen",g:3},{t:","},{t:"andererseits",g:4},{t:"fehlt",g:5},{t:"mir",g:6},{t:"das Geld",g:7}],en:[{t:"On the one hand",g:0},{t:"I",g:2},{t:"want",g:1},{t:"to travel",g:3},{t:","},{t:"on the other hand",g:4},{t:"I",g:6},{t:"lack",g:5},{t:"the money",g:7}],hi:[{t:"एक तरफ़",g:0},{t:"मैं",g:2},{t:"यात्रा करना",g:3},{t:"चाहता हूँ",g:1},{t:","},{t:"दूसरी तरफ़",g:4},{t:"मेरे पास",g:6},{t:"पैसे",g:7},{t:"नहीं हैं",g:5}],hiTranslit:"ek taraf main yatra karna chahta hoon, dusri taraf mere paas paise nahin hain",note:'"einerseits" and "andererseits" each occupy position 1 in their own clause, forcing inversion ("möchte ich", "fehlt mir") — German marks the contrast with two word-order shifts that neither English nor Hindi makes.'}]},{id:"conj-dass",category:"conjunction",de:"dass",en:["that"],hi:["कि"],hiTranslit:"ki",ipa:"das",deva:"डस्",level:"A1",theme:"logic",illustration:"conj-dass",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Ich",g:0},{t:"weiß",g:1},{t:","},{t:"dass",g:2},{t:"du",g:3},{t:"müde",g:4},{t:"bist",g:5}],en:[{t:"I",g:0},{t:"know",g:1},{t:","},{t:"that",g:2},{t:"you",g:3},{t:"are",g:5},{t:"tired",g:4}],hi:[{t:"मैं",g:0},{t:"जानता हूँ",g:1},{t:","},{t:"कि",g:2},{t:"तुम",g:3},{t:"थके हुए",g:4},{t:"हो",g:5}],hiTranslit:"main jaanta hoon, ki tum thake hue ho",note:'"dass" sends "bist" to the very end of its clause — the same clause-final instinct a Hindi speaker already has by default, since Hindi always keeps the verb last.'}]},{id:"conj-weil",category:"conjunction",de:"weil",en:["because"],hi:["क्योंकि","इसलिए कि"],hiTranslit:"kyonki / isliye ki",ipa:"vaɪ̯l",deva:"वाइल",level:"A1",theme:"logic",illustration:"conj-weil",type:"subordinating",verbPosition:"final",notes:'Sends the verb to the end of its clause — exactly what Hindi does by default. Contrast with denn: same meaning ("because"), but denn leaves the verb in position 2 instead of sending it to the end.',examples:[{de:[{t:"Ich",g:0},{t:"bleibe",g:1},{t:"zu Hause",g:2},{t:"weil",g:3},{t:"ich",g:4},{t:"krank",g:5},{t:"bin",g:6}],en:[{t:"I",g:0},{t:"am staying",g:1},{t:"at home",g:2},{t:"because",g:3},{t:"I",g:4},{t:"am",g:6},{t:"sick",g:5}],hi:[{t:"मैं",g:0},{t:"घर पर",g:2},{t:"रहता हूँ",g:1},{t:"क्योंकि",g:3},{t:"मैं",g:4},{t:"बीमार",g:5},{t:"हूँ",g:6}],hiTranslit:"main ghar par rehta hoon kyonki main beemaar hoon",note:"After weil the German verb moves to the very end — matching Hindi word order exactly, while English keeps it in the middle."}]},{id:"conj-wenn",category:"conjunction",de:"wenn",en:["if","when(ever)"],hi:["अगर","जब"],hiTranslit:"agar / jab",ipa:"vɛn",deva:"वेन्",level:"A1",theme:"time",illustration:"conj-wenn",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Ich",g:0},{t:"bin",g:1},{t:"glücklich",g:2},{t:","},{t:"wenn",g:3},{t:"du",g:4},{t:"hier",g:5},{t:"bist",g:6}],en:[{t:"I",g:0},{t:"am",g:1},{t:"happy",g:2},{t:","},{t:"when",g:3},{t:"you",g:4},{t:"are",g:6},{t:"here",g:5}],hi:[{t:"मैं",g:0},{t:"ख़ुश",g:2},{t:"होता हूँ",g:1},{t:","},{t:"जब",g:3},{t:"तुम",g:4},{t:"यहाँ",g:5},{t:"होते हो",g:6}],hiTranslit:"main khush hota hoon, jab tum yahaan hote ho",note:`"wenn" pushes "bist" to the end of its clause, just as Hindi's "होते हो" naturally falls at the end of its own clause by default.`}]},{id:"conj-als",category:"conjunction",de:"als",en:["when (single past occasion)"],hi:["जब"],hiTranslit:"jab",ipa:"als",deva:"अल्स्",level:"A2",theme:"time",illustration:"conj-als",type:"subordinating",verbPosition:"final",notes:'Used only for a single completed event in the past — for repeated or habitual "when", German switches to "wenn" instead; Hindi "जब" covers both without distinguishing them.',examples:[{de:[{t:"Als",g:0},{t:"ich",g:1},{t:"Kind",g:2},{t:"war",g:3},{t:","},{t:"wohnte",g:4},{t:"ich",g:1},{t:"in Berlin",g:5}],en:[{t:"When",g:0},{t:"I",g:1},{t:"was",g:3},{t:"a child",g:2},{t:","},{t:"I",g:1},{t:"lived",g:4},{t:"in Berlin",g:5}],hi:[{t:"जब",g:0},{t:"मैं",g:1},{t:"बच्चा",g:2},{t:"था",g:3},{t:","},{t:"तब"},{t:"मैं",g:1},{t:"बर्लिन में",g:5},{t:"रहता था",g:4}],hiTranslit:"jab main baccha tha, tab main Berlin mein rehta tha",note:`"als" pushes "war" to the end of its own clause; Hindi's "था" also falls at the end of its clause, so the two languages already agree here — English is the odd one out, keeping "was" in the middle.`}]},{id:"conj-ob",category:"conjunction",de:"ob",en:["whether","if"],hi:["क्या... या नहीं","कि"],hiTranslit:"kya... ya nahin / ki",ipa:"ɔp",deva:"ऑप्",level:"A2",theme:"logic",illustration:"conj-ob",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Ich",g:0},{t:"weiß nicht",g:1},{t:","},{t:"ob",g:2},{t:"er",g:3},{t:"kommt",g:4}],en:[{t:"I",g:0},{t:"do not know",g:1},{t:","},{t:"whether",g:2},{t:"he",g:3},{t:"is coming",g:4}],hi:[{t:"मुझे",g:0},{t:"नहीं पता",g:1},{t:","},{t:"कि",g:2},{t:"वह",g:3},{t:"आएगा या नहीं",g:4}],hiTranslit:"mujhe nahin pata ki vah aayega ya nahin",note:`"ob" sends "kommt" to the end of its clause like the other subordinators — Hindi's "आएगा" sits at the end too, though its own "या नहीं" tag spells out the "whether" meaning that German leaves to "ob" alone.`}]},{id:"conj-obwohl",category:"conjunction",de:"obwohl",en:["although","even though"],hi:["हालांकि","यद्यपि"],hiTranslit:"haalaanki / yadyapi",ipa:"ɔpˈvoːl",deva:"ऑप्वोल्",level:"A2",theme:"logic",illustration:"conj-obwohl",type:"subordinating",verbPosition:"final",notes:'Contrast with trotzdem: both express "although / despite that", but obwohl subordinates its clause (verb final) while trotzdem is an adverbial connector that inverts subject and verb instead — same concessive meaning, two different mechanisms.',examples:[{de:[{t:"Ich",g:0},{t:"gehe raus",g:1},{t:","},{t:"obwohl",g:2},{t:"es",g:3},{t:"regnet",g:4}],en:[{t:"I",g:0},{t:"am going out",g:1},{t:","},{t:"although",g:2},{t:"it",g:3},{t:"is raining",g:4}],hi:[{t:"मैं",g:0},{t:"बाहर जा रहा हूँ",g:1},{t:","},{t:"हालांकि",g:2},{t:"बारिश",g:3},{t:"हो रही है",g:4}],hiTranslit:"main baahar ja raha hoon, haalaanki baarish ho rahi hai",note:'"obwohl" sends "regnet" to the end of its clause; compare "trotzdem" later in this set, which expresses the same contrast but inverts the verb instead of moving it to the end.'}]},{id:"conj-damit",category:"conjunction",de:"damit",en:["so that","in order that"],hi:["ताकि"],hiTranslit:"taaki",ipa:"daˈmɪt",deva:"डमिट्",level:"A2",theme:"logic",illustration:"conj-damit",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Ich",g:0},{t:"lerne",g:1},{t:"Deutsch",g:2},{t:","},{t:"damit",g:3},{t:"ich",g:4},{t:"in Berlin",g:5},{t:"arbeiten kann",g:6}],en:[{t:"I",g:0},{t:"am learning",g:1},{t:"German",g:2},{t:","},{t:"so that",g:3},{t:"I",g:4},{t:"can work",g:6},{t:"in Berlin",g:5}],hi:[{t:"मैं",g:0},{t:"जर्मन",g:2},{t:"सीखता हूँ",g:1},{t:","},{t:"ताकि",g:3},{t:"मैं",g:4},{t:"बर्लिन में",g:5},{t:"काम कर सकूँ",g:6}],hiTranslit:"main German seekhta hoon, taaki main Berlin mein kaam kar sakoon",note:`"damit" pushes the whole verb group "arbeiten kann" to the end of its clause — Hindi's own clause-final verb naturally mirrors this bracket, while English keeps "can" and "work" split apart in the middle.`}]},{id:"conj-bevor",category:"conjunction",de:"bevor",en:["before"],hi:["इससे पहले कि"],hiTranslit:"isse pehle ki",ipa:"bəˈfoːɐ̯",deva:"बेफ़ोअ",level:"A2",theme:"time",illustration:"conj-bevor",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Ich",g:0},{t:"esse",g:1},{t:","},{t:"bevor",g:2},{t:"ich",g:3},{t:"schlafen gehe",g:4}],en:[{t:"I",g:0},{t:"eat",g:1},{t:","},{t:"before",g:2},{t:"I",g:3},{t:"go to sleep",g:4}],hi:[{t:"मैं",g:0},{t:"खाना खाता हूँ",g:1},{t:","},{t:"इससे पहले कि",g:2},{t:"मैं",g:3},{t:"सोने जाता हूँ",g:4}],hiTranslit:"main khaana khaata hoon, isse pehle ki main sone jaata hoon",note:`"bevor" sends "gehe" to the end of its own clause; Hindi's "जाता हूँ" already sits at the end of its clause without any extra effort, since that is simply where Hindi verbs live.`}]},{id:"conj-nachdem",category:"conjunction",de:"nachdem",en:["after"],hi:["इसके बाद कि","जब...तब"],hiTranslit:"iske baad ki / jab...tab",ipa:"naːxˈdeːm",deva:"नाख़्डेम्",level:"A2",theme:"time",illustration:"conj-nachdem",type:"subordinating",verbPosition:"final",notes:"Almost always paired with Perfekt in its own clause and a simple tense in the main clause, marking that the nachdem-action finished first.",examples:[{de:[{t:"Nachdem",g:0},{t:"ich",g:1},{t:"gegessen habe",g:2},{t:","},{t:"gehe",g:3},{t:"ich",g:1},{t:"spazieren",g:4}],en:[{t:"After",g:0},{t:"I",g:1},{t:"have eaten",g:2},{t:","},{t:"I",g:1},{t:"go",g:3},{t:"for a walk",g:4}],hi:[{t:"इसके बाद कि",g:0},{t:"मैंने",g:1},{t:"खाना खाया है",g:2},{t:","},{t:"मैं",g:1},{t:"टहलने",g:4},{t:"जाता हूँ",g:3}],hiTranslit:"iske baad ki maine khaana khaaya hai, main tehalne jaata hoon",note:`"nachdem" pushes "gegessen habe" to the end of its own clause as one unit; Hindi's "खाया है" behaves the same way, landing at the very end of its clause by default.`}]},{id:"conj-waehrend",category:"conjunction",de:"während",en:["while","whereas"],hi:["जबकि"],hiTranslit:"jabki",ipa:"ˈvɛːrənt",deva:"वैरेन्ट्",level:"A2",theme:"time",illustration:"conj-waehrend",type:"subordinating",verbPosition:"final",notes:'Can mark either simultaneity ("while") or contrast ("whereas") — context decides which; compare "wohingegen" later in this set, which is reserved for the purely contrastive sense.',examples:[{de:[{t:"Während",g:0},{t:"ich",g:1},{t:"koche",g:2},{t:","},{t:"liest",g:3},{t:"du",g:4},{t:"ein Buch",g:5}],en:[{t:"While",g:0},{t:"I",g:1},{t:"cook",g:2},{t:","},{t:"you",g:4},{t:"read",g:3},{t:"a book",g:5}],hi:[{t:"जबकि",g:0},{t:"मैं",g:1},{t:"खाना बनाता हूँ",g:2},{t:","},{t:"तुम",g:4},{t:"एक किताब",g:5},{t:"पढ़ते हो",g:3}],hiTranslit:"jabki main khaana banaata hoon, tum ek kitaab padhte ho",note:`"während" pushes "koche" to the end of its own clause; Hindi's "बनाता हूँ" does the same by default, while English keeps "cook" right after its subject.`}]},{id:"conj-seitdem",category:"conjunction",de:"seitdem",en:["since (temporal)"],hi:["जब से"],hiTranslit:"jab se",ipa:"zaɪtˈdeːm",deva:"ज़ाइट्डेम्",level:"B1",theme:"time",illustration:"conj-seitdem",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Seitdem",g:0},{t:"sie",g:1},{t:"in Berlin",g:2},{t:"wohnt",g:3},{t:","},{t:"ist",g:4},{t:"sie",g:1},{t:"glücklich",g:5}],en:[{t:"Since",g:0},{t:"she",g:1},{t:"has lived",g:3},{t:"in Berlin",g:2},{t:","},{t:"she",g:1},{t:"has been",g:4},{t:"happy",g:5}],hi:[{t:"जब से",g:0},{t:"वह",g:1},{t:"बर्लिन में",g:2},{t:"रहती है",g:3},{t:","},{t:"वह",g:1},{t:"ख़ुश",g:5},{t:"है",g:4}],hiTranslit:"jab se vah Berlin mein rehti hai, vah khush hai",note:`"seitdem" sends "wohnt" to the end of its own clause; Hindi's "रहती है" already sits last by default, matching German exactly here.`}]},{id:"conj-bis",category:"conjunction",de:"bis",en:["until"],hi:["जब तक"],hiTranslit:"jab tak",ipa:"bɪs",deva:"बिस्",level:"A1",theme:"time",illustration:"conj-bis",type:"subordinating",verbPosition:"final",notes:"Also exists as a preposition governing a noun (bis Freitag); as a conjunction it introduces a full clause instead, and that clause still sends its verb to the end.",examples:[{de:[{t:"Ich",g:0},{t:"warte",g:1},{t:","},{t:"bis",g:2},{t:"du",g:3},{t:"fertig",g:4},{t:"bist",g:5}],en:[{t:"I",g:0},{t:"wait",g:1},{t:","},{t:"until",g:2},{t:"you",g:3},{t:"are",g:5},{t:"ready",g:4}],hi:[{t:"मैं",g:0},{t:"इंतज़ार करता हूँ",g:1},{t:","},{t:"जब तक",g:2},{t:"तुम",g:3},{t:"तैयार",g:4},{t:"नहीं हो",g:5}],hiTranslit:"main intezaar karta hoon, jab tak tum taiyaar nahin ho",note:`"bis" sends "bist" to the end of its clause; Hindi's idiom "जब तक... नहीं" also keeps its verb clause-final, though it adds a negation that German's "bis" does not need.`}]},{id:"conj-falls",category:"conjunction",de:"falls",en:["in case","if"],hi:["अगर","यदि"],hiTranslit:"agar / yadi",ipa:"fals",deva:"फ़ल्स्",level:"A2",theme:"logic",illustration:"conj-falls",type:"subordinating",verbPosition:"final",notes:'A more tentative, hypothetical "if" than "wenn" — often used for conditions that may not arise at all, closer to English "in case".',examples:[{de:[{t:"Ruf mich an",g:0},{t:","},{t:"falls",g:1},{t:"du",g:2},{t:"Hilfe",g:3},{t:"brauchst",g:4}],en:[{t:"Call me",g:0},{t:","},{t:"in case",g:1},{t:"you",g:2},{t:"need",g:4},{t:"help",g:3}],hi:[{t:"मुझे फ़ोन करो",g:0},{t:","},{t:"अगर",g:1},{t:"तुम्हें",g:2},{t:"मदद",g:3},{t:"चाहिए",g:4}],hiTranslit:"mujhe phone karo, agar tumhein madad chahiye",note:`"falls" sends "brauchst" to the end of its clause; Hindi's "चाहिए" naturally closes its clause too, needing no special adjustment for the conditional meaning.`}]},{id:"conj-sobald",category:"conjunction",de:"sobald",en:["as soon as"],hi:["ज्यों ही","जैसे ही"],hiTranslit:"jyon hi / jaise hi",ipa:"zoːˈbalt",deva:"ज़ोबल्ट्",level:"B1",theme:"time",illustration:"conj-sobald",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Sobald",g:0},{t:"der Regen",g:1},{t:"aufhört",g:2},{t:","},{t:"gehen",g:3},{t:"wir",g:4},{t:"raus",g:5}],en:[{t:"As soon as",g:0},{t:"the rain",g:1},{t:"stops",g:2},{t:","},{t:"we",g:4},{t:"go",g:3},{t:"outside",g:5}],hi:[{t:"ज्यों ही",g:0},{t:"बारिश",g:1},{t:"रुकती है",g:2},{t:","},{t:"हम",g:4},{t:"बाहर",g:5},{t:"जाते हैं",g:3}],hiTranslit:"jyon hi baarish rukti hai, hum baahar jaate hain",note:`"sobald" pushes "aufhört" to the end of its own clause; Hindi's "रुकती है" lands at the end too, since that is simply the default position for a Hindi verb.`}]},{id:"conj-solange",category:"conjunction",de:"solange",en:["as long as"],hi:["जब तक"],hiTranslit:"jab tak",ipa:"zoːˈlaŋə",deva:"ज़ोलंगे",level:"B1",theme:"time",illustration:"conj-solange",type:"subordinating",verbPosition:"final",notes:'Shares its Hindi gloss "जब तक" with "bis" — context (a continuing state vs. an end point) tells them apart, since English and Hindi do not mark the difference as sharply as German does.',examples:[{de:[{t:"Ich",g:0},{t:"bleibe",g:1},{t:"hier",g:2},{t:","},{t:"solange",g:3},{t:"du",g:4},{t:"bleibst",g:5}],en:[{t:"I",g:0},{t:"stay",g:1},{t:"here",g:2},{t:","},{t:"as long as",g:3},{t:"you",g:4},{t:"stay",g:5}],hi:[{t:"मैं",g:0},{t:"यहाँ",g:2},{t:"रहता हूँ",g:1},{t:","},{t:"जब तक",g:3},{t:"तुम",g:4},{t:"रहते हो",g:5}],hiTranslit:"main yahaan rehta hoon, jab tak tum rehte ho",note:`"solange" sends "bleibst" to the end of its clause; Hindi's "रहते हो" is already there by default, since Hindi verbs always close out their clause.`}]},{id:"conj-indem",category:"conjunction",de:"indem",en:["by (doing something)"],hi:["इस तरह कि","...करके"],hiTranslit:"is tarah ki / karke",ipa:"ɪnˈdeːm",deva:"इन्डेम्",level:"B1",theme:"logic",illustration:"conj-indem",type:"subordinating",verbPosition:"final",notes:`Describes the means by which something is achieved — closest to English "by ...ing"; Hindi's participial "करके" ("having done") can capture the same means-relationship without a full second clause.`,examples:[{de:[{t:"Ich",g:0},{t:"lerne",g:1},{t:"Deutsch",g:2},{t:","},{t:"indem",g:3},{t:"ich",g:4},{t:"jeden Tag",g:5},{t:"übe",g:6}],en:[{t:"I",g:0},{t:"learn",g:1},{t:"German",g:2},{t:","},{t:"in that",g:3},{t:"I",g:4},{t:"practise",g:6},{t:"every day",g:5}],hi:[{t:"मैं",g:0},{t:"जर्मन",g:2},{t:"सीखता हूँ",g:1},{t:","},{t:"इस तरह कि",g:3},{t:"मैं",g:4},{t:"हर दिन",g:5},{t:"अभ्यास करता हूँ",g:6}],hiTranslit:"main German seekhta hoon, is tarah ki main har din abhyaas karta hoon",note:`"indem" sends "übe" to the end of its own clause; Hindi's "करता हूँ" also closes its clause by default, while English restructures the whole idea as a gerund phrase instead of a full clause.`}]},{id:"conj-sodass",category:"conjunction",de:"sodass",en:["so that","with the result that"],hi:["जिससे कि","ताकि"],hiTranslit:"jisse ki / taaki",ipa:"zoːˈdas",deva:"ज़ोडस्",level:"B1",theme:"logic",illustration:"conj-sodass",type:"subordinating",verbPosition:"final",notes:`Marks a RESULT ("so that, as a result"), unlike "damit" which marks a PURPOSE ("so that, in order to") — German keeps the two apart; Hindi's "ताकि" often covers both.`,examples:[{de:[{t:"Der Regen",g:0},{t:"war",g:1},{t:"stark",g:2},{t:","},{t:"sodass",g:3},{t:"wir",g:4},{t:"zu Hause",g:5},{t:"blieben",g:6}],en:[{t:"The rain",g:0},{t:"was",g:1},{t:"hard",g:2},{t:","},{t:"so that",g:3},{t:"we",g:4},{t:"stayed",g:6},{t:"home",g:5}],hi:[{t:"बारिश",g:0},{t:"तेज़",g:2},{t:"थी",g:1},{t:","},{t:"जिससे कि",g:3},{t:"हम",g:4},{t:"घर पर",g:5},{t:"रहे",g:6}],hiTranslit:"baarish tez thi, jisse ki hum ghar par rahe",note:`"sodass" sends "blieben" to the end of its own clause; Hindi's "रहे" is already clause-final by default, matching German's placement here.`}]},{id:"conj-obgleich",category:"conjunction",de:"obgleich",en:["although","even though"],hi:["यद्यपि"],hiTranslit:"yadyapi",ipa:"ɔpˈɡlaɪç",deva:"ऑप्ग्लाइख़्",level:"B1",theme:"logic",illustration:"conj-obgleich",type:"subordinating",verbPosition:"final",notes:'A more formal, literary synonym for "obwohl" — same meaning and the same clause-final verb placement, used mainly in writing.',examples:[{de:[{t:"Obgleich",g:0},{t:"das Wetter",g:1},{t:"kalt",g:2},{t:"ist",g:3},{t:","},{t:"gehe",g:4},{t:"ich",g:5},{t:"schwimmen",g:6}],en:[{t:"Although",g:0},{t:"the weather",g:1},{t:"is",g:3},{t:"cold",g:2},{t:","},{t:"I",g:5},{t:"go",g:4},{t:"swimming",g:6}],hi:[{t:"यद्यपि",g:0},{t:"मौसम",g:1},{t:"ठंडा",g:2},{t:"है",g:3},{t:","},{t:"मैं",g:5},{t:"तैरने",g:6},{t:"जाता हूँ",g:4}],hiTranslit:"yadyapi mausam thanda hai, main tairne jaata hoon",note:`"obgleich" sends "ist" to the end of its own clause, exactly like its everyday synonym "obwohl"; Hindi's "है" is already clause-final by default.`}]},{id:"conj-sofern",category:"conjunction",de:"sofern",en:["provided that","as long as"],hi:["बशर्ते कि"],hiTranslit:"basharte ki",ipa:"zoːˈfɛrn",deva:"ज़ोफ़ेर्न्",level:"B1",theme:"logic",illustration:"conj-sofern",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Ich",g:0},{t:"komme mit",g:1},{t:","},{t:"sofern",g:2},{t:"ich",g:3},{t:"Zeit",g:4},{t:"habe",g:5}],en:[{t:"I",g:0},{t:"will come along",g:1},{t:","},{t:"provided that",g:2},{t:"I",g:3},{t:"have",g:5},{t:"time",g:4}],hi:[{t:"मैं",g:0},{t:"साथ आऊँगा",g:1},{t:","},{t:"बशर्ते कि",g:2},{t:"मुझे",g:3},{t:"समय",g:4},{t:"मिले",g:5}],hiTranslit:"main saath aaunga, basharte ki mujhe samay mile",note:`"sofern" sends "habe" to the end of its own clause; Hindi's "मिले" closes its clause the same way, needing no adjustment for the conditional sense.`}]},{id:"conj-zumal",category:"conjunction",de:"zumal",en:["especially since","particularly as"],hi:["ख़ासकर क्योंकि"],hiTranslit:"khaaskar kyonki",ipa:"tsuˈmaːl",deva:"त्सुमाल्",level:"B1",theme:"logic",illustration:"conj-zumal",type:"subordinating",verbPosition:"final",notes:'Adds emphasis to a reason already implied by context — stronger than plain "weil", closer to "especially since / because".',examples:[{de:[{t:"Ich",g:0},{t:"bleibe zu Hause",g:1},{t:","},{t:"zumal",g:2},{t:"es",g:3},{t:"regnet",g:4}],en:[{t:"I",g:0},{t:"am staying home",g:1},{t:","},{t:"especially since",g:2},{t:"it",g:3},{t:"is raining",g:4}],hi:[{t:"मैं",g:0},{t:"घर पर रहता हूँ",g:1},{t:","},{t:"ख़ासकर क्योंकि",g:2},{t:"बारिश",g:3},{t:"हो रही है",g:4}],hiTranslit:"main ghar par rehta hoon, khaaskar kyonki baarish ho rahi hai",note:`"zumal" sends "regnet" to the end of its own clause; Hindi's "हो रही है" is already clause-final, matching German's word order exactly.`}]},{id:"conj-da",category:"conjunction",de:"da",en:["since","as (causal)"],hi:["चूँकि"],hiTranslit:"choonki",ipa:"daː",deva:"डा",level:"A2",theme:"logic",illustration:"conj-da",type:"subordinating",verbPosition:"final",notes:'A more formal causal conjunction than "weil", often placed at the very start of the sentence; both send their verb to the end of the clause.',examples:[{de:[{t:"Da",g:0},{t:"ich",g:1},{t:"müde",g:2},{t:"bin",g:3},{t:","},{t:"gehe",g:4},{t:"ich",g:1},{t:"schlafen",g:5}],en:[{t:"Since",g:0},{t:"I",g:1},{t:"am",g:3},{t:"tired",g:2},{t:","},{t:"I",g:1},{t:"am going",g:4},{t:"to sleep",g:5}],hi:[{t:"चूँकि",g:0},{t:"मैं",g:1},{t:"थका हुआ",g:2},{t:"हूँ",g:3},{t:","},{t:"मैं",g:1},{t:"सोने",g:5},{t:"जा रहा हूँ",g:4}],hiTranslit:"choonki main thaka hua hoon, main sone ja raha hoon",note:`"da" pushes "bin" to the end of its own clause, just like "weil"; Hindi's "हूँ" is already clause-final by default, so a Hindi speaker feels no strangeness here at all.`}]},{id:"conj-wie",category:"conjunction",de:"wie",en:["as (comparative)"],hi:["जैसे"],hiTranslit:"jaise",ipa:"viː",deva:"वी",level:"A1",theme:"logic",illustration:"conj-wie",type:"subordinating",verbPosition:"final",notes:'Compares a whole clause, not just a noun — this comparative "wie" is distinct from the question word "wie" ("how"), though the two share a spelling.',examples:[{de:[{t:"Sie",g:0},{t:"kocht",g:1},{t:","},{t:"wie",g:2},{t:"ihre Mutter",g:3},{t:"kocht",g:4}],en:[{t:"She",g:0},{t:"cooks",g:1},{t:","},{t:"as",g:2},{t:"her mother",g:3},{t:"cooks",g:4}],hi:[{t:"वह",g:0},{t:"खाना बनाती है",g:1},{t:","},{t:"जैसे",g:2},{t:"उसकी माँ",g:3},{t:"बनाती है",g:4}],hiTranslit:"vah khaana banaati hai, jaise uski maa banaati hai",note:`"wie" sends the second "kocht" to the end of its own clause; Hindi's "बनाती है" closes its clause the same way, so the comparison feels perfectly natural in both.`}]},{id:"conj-soweit",category:"conjunction",de:"soweit",en:["as far as"],hi:["जहाँ तक"],hiTranslit:"jahaan tak",ipa:"zoːˈvaɪt",deva:"ज़ोवाइट्",level:"B1",theme:"logic",illustration:"conj-soweit",type:"subordinating",verbPosition:"final",notes:'Limits a claim to what the speaker actually knows — "as far as I know" is its most common use.',examples:[{de:[{t:"Soweit",g:0},{t:"ich",g:1},{t:"weiß",g:2},{t:","},{t:"kommt",g:3},{t:"er",g:4},{t:"morgen",g:5}],en:[{t:"As far as",g:0},{t:"I",g:1},{t:"know",g:2},{t:","},{t:"he",g:4},{t:"is coming",g:3},{t:"tomorrow",g:5}],hi:[{t:"जहाँ तक",g:0},{t:"मुझे",g:1},{t:"पता है",g:2},{t:","},{t:"वह",g:4},{t:"कल",g:5},{t:"आ रहा है",g:3}],hiTranslit:"jahaan tak mujhe pata hai, vah kal aa raha hai",note:`"soweit" sends "weiß" to the end of its own clause; Hindi's "पता है" ends its clause the same way, by default.`}]},{id:"conj-wohingegen",category:"conjunction",de:"wohingegen",en:["whereas","while (contrastive)"],hi:["जबकि"],hiTranslit:"jabki",ipa:"voːhɪnˈɡeːɡn̩",deva:"वोहिन्गेगन्",level:"B1",theme:"logic",illustration:"conj-wohingegen",type:"subordinating",verbPosition:"final",notes:'Reserved for pure contrast, never simultaneity — unlike "während", which can mean either "while" or "whereas" depending on context.',examples:[{de:[{t:"Er",g:0},{t:"mag",g:1},{t:"Kaffee",g:2},{t:","},{t:"wohingegen",g:3},{t:"sie",g:4},{t:"Tee",g:5},{t:"bevorzugt",g:6}],en:[{t:"He",g:0},{t:"likes",g:1},{t:"coffee",g:2},{t:","},{t:"whereas",g:3},{t:"she",g:4},{t:"prefers",g:6},{t:"tea",g:5}],hi:[{t:"उसे",g:0},{t:"कॉफ़ी",g:2},{t:"पसंद है",g:1},{t:","},{t:"जबकि",g:3},{t:"वह",g:4},{t:"चाय को",g:5},{t:"प्राथमिकता देती है",g:6}],hiTranslit:"use coffee pasand hai, jabki vah chai ko praathmikta deti hai",note:`"wohingegen" sends "bevorzugt" to the end of its own clause; Hindi's "देती है" lands at the end too, matching German exactly here.`}]},{id:"conj-anstatt-dass",category:"conjunction",de:"anstatt dass",en:["instead of (+ clause)"],hi:["इसके बजाय कि"],hiTranslit:"iske bajaay ki",ipa:"anˈʃtat das",deva:"अन्श्टट् डस्",level:"B1",theme:"logic",illustration:"conj-anstatt-dass",type:"subordinating",verbPosition:"final",notes:'Needs its own subject and verb, unlike the simpler preposition "anstatt + noun" — the two share a root but behave differently in a sentence.',examples:[{de:[{t:"Er",g:0},{t:"sieht fern",g:1},{t:","},{t:"anstatt dass",g:2},{t:"er",g:3},{t:"lernt",g:4}],en:[{t:"He",g:0},{t:"watches TV",g:1},{t:","},{t:"instead of",g:2},{t:"him",g:3},{t:"studying",g:4}],hi:[{t:"वह",g:0},{t:"टीवी देखता है",g:1},{t:","},{t:"इसके बजाय कि",g:2},{t:"वह",g:3},{t:"पढ़ता है",g:4}],hiTranslit:"vah TV dekhta hai, iske bajaay ki vah padhta hai",note:`"anstatt dass" sends "lernt" to the end of its own clause; Hindi's "पढ़ता है" is clause-final too, while English avoids a second clause altogether by turning the verb into a gerund.`}]},{id:"conj-ohne-dass",category:"conjunction",de:"ohne dass",en:["without (+ clause)"],hi:["बिना इसके कि"],hiTranslit:"bina iske ki",ipa:"ˈoːnə das",deva:"ओने डस्",level:"B1",theme:"logic",illustration:"conj-ohne-dass",type:"subordinating",verbPosition:"final",notes:'Needs its own subject and verb, unlike the simpler preposition "ohne + noun"; the clause after it describes something that notably did not happen.',examples:[{de:[{t:"Sie",g:0},{t:"ging weg",g:1},{t:","},{t:"ohne dass",g:2},{t:"sie",g:3},{t:"sich verabschiedete",g:4}],en:[{t:"She",g:0},{t:"left",g:1},{t:","},{t:"without",g:2},{t:"her",g:3},{t:"saying goodbye",g:4}],hi:[{t:"वह",g:0},{t:"चली गई",g:1},{t:","},{t:"बिना इसके कि",g:2},{t:"उसने",g:3},{t:"अलविदा कहा",g:4}],hiTranslit:"vah chali gayi, bina iske ki usne alvida kaha",note:`"ohne dass" sends "verabschiedete" to the end of its own clause; Hindi's "कहा" ends its clause the same way, while English again turns the missing action into a gerund instead of a second clause.`}]},{id:"conj-ausser-wenn",category:"conjunction",de:"außer wenn",en:["except if","unless"],hi:["जब तक न"],hiTranslit:"jab tak na",ipa:"ˈaʊsɐ vɛn",deva:"आउसा वेन्",level:"B1",theme:"logic",illustration:"conj-ausser-wenn",type:"subordinating",verbPosition:"final",examples:[{de:[{t:"Ich",g:0},{t:"komme",g:1},{t:","},{t:"außer wenn",g:2},{t:"es",g:3},{t:"regnet",g:4}],en:[{t:"I",g:0},{t:"will come",g:1},{t:","},{t:"unless",g:2},{t:"it",g:3},{t:"rains",g:4}],hi:[{t:"मैं",g:0},{t:"आऊँगा",g:1},{t:","},{t:"जब तक",g:2},{t:"बारिश",g:3},{t:"न हो",g:4}],hiTranslit:"main aaunga, jab tak baarish na ho",note:`"außer wenn" sends "regnet" to the end of its own clause; Hindi's negated "न हो" also closes its clause at the end, matching German's placement despite the added negation.`}]},{id:"conj-wenngleich",category:"conjunction",de:"wenngleich",en:["although","even though"],hi:["यद्यपि"],hiTranslit:"yadyapi",ipa:"vɛnˈɡlaɪç",deva:"वेन्ग्लाइख़्",level:"B1",theme:"logic",illustration:"conj-wenngleich",type:"subordinating",verbPosition:"final",notes:'Yet another formal synonym for "obwohl" / "obgleich" — all three subordinate their clause the same way; the choice between them is a matter of register, not grammar.',examples:[{de:[{t:"Wenngleich",g:0},{t:"er",g:1},{t:"müde",g:2},{t:"war",g:3},{t:","},{t:"arbeitete",g:4},{t:"er",g:1},{t:"weiter",g:5}],en:[{t:"Even though",g:0},{t:"he",g:1},{t:"was",g:3},{t:"tired",g:2},{t:","},{t:"he",g:1},{t:"kept",g:5},{t:"working",g:4}],hi:[{t:"यद्यपि",g:0},{t:"वह",g:1},{t:"थका हुआ",g:2},{t:"था",g:3},{t:","},{t:"वह",g:1},{t:"काम करता",g:4},{t:"रहा",g:5}],hiTranslit:"yadyapi vah thaka hua tha, vah kaam karta raha",note:`"wenngleich" sends "war" to the end of its own clause, exactly like "obwohl" and "obgleich"; Hindi's "था" is already clause-final by default.`}]},{id:"conj-deshalb",category:"conjunction",de:"deshalb",en:["therefore","for this reason"],hi:["इसलिए"],hiTranslit:"isliye",ipa:"ˈdɛsˌhalp",deva:"डेस्हल्प्",level:"A2",theme:"logic",illustration:"conj-deshalb",type:"adverbial",verbPosition:"inversion",notes:'Looks like a coordinating conjunction but is not one — "deshalb" itself occupies position 1, so the verb must come immediately after it and before the subject. Learners routinely write the wrong "..., deshalb ich bleibe zu Hause" instead of the correct "..., deshalb bleibe ich zu Hause".',examples:[{de:[{t:"Ich",g:0},{t:"bin",g:1},{t:"krank",g:2},{t:","},{t:"deshalb",g:3},{t:"bleibe",g:4},{t:"ich",g:0},{t:"zu Hause",g:5}],en:[{t:"I",g:0},{t:"am",g:1},{t:"sick",g:2},{t:","},{t:"therefore",g:3},{t:"I",g:0},{t:"am staying",g:4},{t:"at home",g:5}],hi:[{t:"मैं",g:0},{t:"बीमार",g:2},{t:"हूँ",g:1},{t:","},{t:"इसलिए",g:3},{t:"मैं",g:0},{t:"घर पर",g:5},{t:"रहता हूँ",g:4}],hiTranslit:"main beemaar hoon, isliye main ghar par rehta hoon",note:'"deshalb" fills position 1 itself, so "bleibe" must follow immediately, before the subject "ich" — the inverted order that gives this whole class of connectors its name.'}]},{id:"conj-deswegen",category:"conjunction",de:"deswegen",en:["therefore","because of this"],hi:["इसी वजह से"],hiTranslit:"isi vajah se",ipa:"ˈdɛsˌveːɡn̩",deva:"डेस्वेगन्",level:"A2",theme:"logic",illustration:"conj-deswegen",type:"adverbial",verbPosition:"inversion",notes:'A near-synonym of "deshalb" that learners often mistake for a coordinating conjunction too — remember it takes position 1, forcing "..., deswegen nehme ich..." rather than the wrongly-ordered "..., deswegen ich nehme...".',examples:[{de:[{t:"Es regnet",g:0},{t:","},{t:"deswegen",g:1},{t:"nehme",g:2},{t:"ich",g:3},{t:"einen Regenschirm",g:4}],en:[{t:"It is raining",g:0},{t:","},{t:"therefore",g:1},{t:"I",g:3},{t:"am taking",g:2},{t:"an umbrella",g:4}],hi:[{t:"बारिश हो रही है",g:0},{t:","},{t:"इसी वजह से",g:1},{t:"मैं",g:3},{t:"छाता",g:4},{t:"ले रहा हूँ",g:2}],hiTranslit:"baarish ho rahi hai, isi vajah se main chhaata le raha hoon",note:'"deswegen" occupies position 1, so "nehme" comes right after it and before "ich" — inversion, not the verb-second order a true coordinator would leave untouched.'}]},{id:"conj-darum",category:"conjunction",de:"darum",en:["therefore","that's why"],hi:["इसलिए"],hiTranslit:"isliye",ipa:"daˈrʊm",deva:"डरुम्",level:"A2",theme:"logic",illustration:"conj-darum",type:"adverbial",verbPosition:"inversion",notes:'Colloquial and extremely common — just as easy to mistake for a coordinator as "deshalb"; the verb must still follow it immediately, before the subject, not after.',examples:[{de:[{t:"Ich habe keine Zeit",g:0},{t:","},{t:"darum",g:1},{t:"kann",g:2},{t:"ich",g:3},{t:"nicht kommen",g:4}],en:[{t:"I have no time",g:0},{t:","},{t:"that's why",g:1},{t:"I",g:3},{t:"cannot",g:2},{t:"come",g:4}],hi:[{t:"मेरे पास समय नहीं है",g:0},{t:","},{t:"इसलिए",g:1},{t:"मैं",g:3},{t:"आ",g:4},{t:"नहीं सकता",g:2}],hiTranslit:"mere paas samay nahin hai, isliye main nahin aa sakta",note:'"darum" takes position 1, so "kann" immediately follows it, before "ich" — inversion, exactly like every other connector in this set.'}]},{id:"conj-daher",category:"conjunction",de:"daher",en:["therefore","hence"],hi:["इसलिए"],hiTranslit:"isliye",ipa:"daˈheːɐ̯",deva:"डहेअ",level:"B1",theme:"logic",illustration:"conj-daher",type:"adverbial",verbPosition:"inversion",notes:'A slightly more formal "therefore" than "darum" — same trap for learners, who often default to treating it as a coordinator and wrongly leave the subject before the verb.',examples:[{de:[{t:"Die Straße war gesperrt",g:0},{t:","},{t:"daher",g:1},{t:"kamen",g:2},{t:"wir",g:3},{t:"zu spät",g:4}],en:[{t:"The road was closed",g:0},{t:","},{t:"hence",g:1},{t:"we",g:3},{t:"arrived",g:2},{t:"late",g:4}],hi:[{t:"सड़क बंद थी",g:0},{t:","},{t:"इसलिए",g:1},{t:"हम",g:3},{t:"देर से",g:4},{t:"पहुँचे",g:2}],hiTranslit:"sadak band thi, isliye hum der se pahunche",note:'"daher" fills position 1, so "kamen" follows immediately, before "wir" — the same inversion every connector in this set requires.'}]},{id:"conj-trotzdem",category:"conjunction",de:"trotzdem",en:["nevertheless","despite that"],hi:["फिर भी"],hiTranslit:"phir bhi",ipa:"ˈtrɔtsdeːm",deva:"ट्रॉत्स्डेम्",level:"A2",theme:"logic",illustration:"conj-trotzdem",type:"adverbial",verbPosition:"inversion",notes:'Contrast with obwohl: both express "although / despite that", but trotzdem is an adverbial connector that inverts the verb ("..., trotzdem ging er...") while obwohl subordinates its own clause and sends the verb to the end instead. Learners often mistake trotzdem for a coordinator and wrongly write "..., trotzdem er ging...".',examples:[{de:[{t:"Es regnete",g:0},{t:","},{t:"trotzdem",g:1},{t:"ging",g:2},{t:"er",g:3},{t:"spazieren",g:4}],en:[{t:"It was raining",g:0},{t:","},{t:"nevertheless",g:1},{t:"he",g:3},{t:"went",g:2},{t:"for a walk",g:4}],hi:[{t:"बारिश हो रही थी",g:0},{t:","},{t:"फिर भी",g:1},{t:"वह",g:3},{t:"टहलने",g:4},{t:"गया",g:2}],hiTranslit:"baarish ho rahi thi, phir bhi vah tehalne gaya",note:'"trotzdem" fills position 1, so "ging" follows immediately before "er" — inversion; compare "obwohl es regnete, ging er spazieren", where the same contrast instead sends the verb to the end of the obwohl-clause.'}]},{id:"conj-dennoch",category:"conjunction",de:"dennoch",en:["nevertheless","yet"],hi:["फिर भी"],hiTranslit:"phir bhi",ipa:"ˈdɛnɔx",deva:"डेनॉख़्",level:"B1",theme:"logic",illustration:"conj-dennoch",type:"adverbial",verbPosition:"inversion",notes:'A more formal synonym of "trotzdem" — same inversion, same trap: learners often leave the subject before the verb, writing "..., dennoch er arbeitete..." instead of "..., dennoch arbeitete er...".',examples:[{de:[{t:"Er war müde",g:0},{t:","},{t:"dennoch",g:1},{t:"arbeitete",g:2},{t:"er",g:3},{t:"weiter",g:4}],en:[{t:"He was tired",g:0},{t:","},{t:"yet",g:1},{t:"he",g:3},{t:"kept",g:4},{t:"working",g:2}],hi:[{t:"वह थका हुआ था",g:0},{t:","},{t:"फिर भी",g:1},{t:"वह",g:3},{t:"काम करता",g:2},{t:"रहा",g:4}],hiTranslit:"vah thaka hua tha, phir bhi vah kaam karta raha",note:'"dennoch" occupies position 1, so "arbeitete" comes right after it, before "er" — the same inversion as its synonym "trotzdem".'}]},{id:"conj-ausserdem",category:"conjunction",de:"außerdem",en:["besides","moreover"],hi:["इसके अलावा"],hiTranslit:"iske alaava",ipa:"ˈaʊsɐdeːm",deva:"आउसआडेम्",level:"A2",theme:"logic",illustration:"conj-ausserdem",type:"adverbial",verbPosition:"inversion",notes:'Adds a new point rather than a reason or a contrast, but grammatically it behaves exactly like "deshalb": it fills position 1, so learners must resist writing "..., außerdem es liegt..." and instead invert to "..., außerdem liegt es...".',examples:[{de:[{t:"Das Hotel ist teuer",g:0},{t:","},{t:"außerdem",g:1},{t:"liegt",g:2},{t:"es",g:3},{t:"weit weg",g:4}],en:[{t:"The hotel is expensive",g:0},{t:","},{t:"moreover",g:1},{t:"it",g:3},{t:"is",g:2},{t:"far away",g:4}],hi:[{t:"होटल महँगा है",g:0},{t:","},{t:"इसके अलावा",g:1},{t:"यह",g:3},{t:"दूर",g:4},{t:"है",g:2}],hiTranslit:"hotel mehnga hai, iske alaava yah door hai",note:'"außerdem" fills position 1, so "liegt" immediately follows it, before "es" — the same inversion every connector here requires, regardless of the meaning it adds.'}]},{id:"conj-zudem",category:"conjunction",de:"zudem",en:["in addition","moreover"],hi:["साथ ही"],hiTranslit:"saath hi",ipa:"tsuˈdeːm",deva:"त्सुडेम्",level:"B1",theme:"logic",illustration:"conj-zudem",type:"adverbial",verbPosition:"inversion",notes:'A more formal synonym of "außerdem" — the same inversion applies: the verb must follow it directly, never the subject, however tempting it is to treat it like "und".',examples:[{de:[{t:"Er spricht drei Sprachen",g:0},{t:","},{t:"zudem",g:1},{t:"lernt",g:2},{t:"er",g:3},{t:"gerade Japanisch",g:4}],en:[{t:"He speaks three languages",g:0},{t:","},{t:"moreover",g:1},{t:"he",g:3},{t:"is currently learning",g:2},{t:"Japanese",g:4}],hi:[{t:"वह तीन भाषाएँ बोलता है",g:0},{t:","},{t:"साथ ही",g:1},{t:"वह",g:3},{t:"अभी जापानी",g:4},{t:"सीख रहा है",g:2}],hiTranslit:"vah teen bhaashaen bolta hai, saath hi vah abhi Japani seekh raha hai",note:'"zudem" occupies position 1, so "lernt" comes immediately after it, before "er" — inversion, as with every connector in this set.'}]},{id:"conj-folglich",category:"conjunction",de:"folglich",en:["consequently","as a result"],hi:["परिणामस्वरूप"],hiTranslit:"parinaamswaroop",ipa:"ˈfɔlklɪç",deva:"फ़ॉल्क्लिख़्",level:"B1",theme:"logic",illustration:"conj-folglich",type:"adverbial",verbPosition:"inversion",notes:'A formal, almost logical "therefore" — grammatically identical to "deshalb": it occupies position 1, forcing the verb to come before the subject rather than after a merely-connecting word.',examples:[{de:[{t:"Er lernt nicht",g:0},{t:","},{t:"folglich",g:1},{t:"fällt",g:2},{t:"er",g:3},{t:"durch",g:2}],en:[{t:"He does not study",g:0},{t:","},{t:"consequently",g:1},{t:"he",g:3},{t:"fails",g:2}],hi:[{t:"वह पढ़ाई नहीं करता",g:0},{t:","},{t:"परिणामस्वरूप",g:1},{t:"वह",g:3},{t:"फेल हो जाता है",g:2}],hiTranslit:"vah padhaai nahin karta, parinaamswaroop vah fail ho jaata hai",note:`"folglich" occupies position 1, so "fällt" comes right after it, before "er"; the separable verb's "durch" still waits at the very end of the clause, reusing the same colour to show it is one verb split in two.`}]},{id:"conj-somit",category:"conjunction",de:"somit",en:["thus","therefore"],hi:["इस तरह"],hiTranslit:"is tarah",ipa:"zoːˈmɪt",deva:"ज़ोमिट्",level:"B1",theme:"logic",illustration:"conj-somit",type:"adverbial",verbPosition:"inversion",notes:'A formal "thus" used to sum up a logical conclusion — grammatically it behaves exactly like "deshalb": position 1, verb immediately after, subject after that. Learners still default to "..., somit die Show ist..." when the correct order is "..., somit ist die Show...".',examples:[{de:[{t:"Alle Tickets sind verkauft",g:0},{t:","},{t:"somit",g:1},{t:"ist",g:2},{t:"die Show",g:3},{t:"ausverkauft",g:4}],en:[{t:"All tickets are sold",g:0},{t:","},{t:"thus",g:1},{t:"the show",g:3},{t:"is",g:2},{t:"sold out",g:4}],hi:[{t:"सभी टिकट बिक चुके हैं",g:0},{t:","},{t:"इस तरह",g:1},{t:"शो",g:3},{t:"हाउसफुल",g:4},{t:"है",g:2}],hiTranslit:"sabhi ticket bik chuke hain, is tarah show housefull hai",note:'"somit" fills position 1, so "ist" follows immediately, before "die Show" — the same inversion as every connector in this set, regardless of how formal it sounds.'}]},{id:"conj-also",category:"conjunction",de:"also",en:["so","thus"],hi:["तो","इसलिए"],hiTranslit:"to / isliye",ipa:"ˈalzoː",deva:"अल्ज़ो",level:"A2",theme:"logic",illustration:"conj-also",type:"adverbial",verbPosition:"inversion",notes:'A filler-like "so" used constantly in spoken German to draw a conclusion — still takes position 1, so the verb must come right after it, before the subject, unlike English "so".',examples:[{de:[{t:"Ich habe keinen Hunger",g:0},{t:","},{t:"also",g:1},{t:"esse",g:2},{t:"ich",g:3},{t:"später",g:4}],en:[{t:"I am not hungry",g:0},{t:","},{t:"so",g:1},{t:"I",g:3},{t:"will eat",g:2},{t:"later",g:4}],hi:[{t:"मुझे भूख नहीं है",g:0},{t:","},{t:"तो",g:1},{t:"मैं",g:3},{t:"बाद में",g:4},{t:"खाऊँगा",g:2}],hiTranslit:"mujhe bhookh nahin hai, to main baad mein khaaunga",note:'"also" fills position 1, so "esse" comes right after it, before "ich" — inversion, even though English "so" would happily sit before its own subject-verb order.'}]},{id:"conj-dann",category:"conjunction",de:"dann",en:["then"],hi:["फिर","तब"],hiTranslit:"phir / tab",ipa:"dan",deva:"डन्",level:"A1",theme:"time",illustration:"conj-dann",type:"adverbial",verbPosition:"inversion",notes:'Sequences one action after another — its most common trap is that learners bolt it onto a clause like "und" and forget it needs the verb to follow it immediately, before the subject.',examples:[{de:[{t:"Wir essen zu Abend",g:0},{t:","},{t:"dann",g:1},{t:"sehen",g:2},{t:"wir",g:3},{t:"einen Film",g:4}],en:[{t:"We eat dinner",g:0},{t:","},{t:"then",g:1},{t:"we",g:3},{t:"watch",g:2},{t:"a film",g:4}],hi:[{t:"हम रात का खाना खाते हैं",g:0},{t:","},{t:"फिर",g:1},{t:"हम",g:3},{t:"एक फ़िल्म",g:4},{t:"देखते हैं",g:2}],hiTranslit:"hum raat ka khaana khaate hain, phir hum ek film dekhte hain",note:'"dann" occupies position 1, so "sehen" comes right after it and before "wir" — inversion, even though it feels as short and simple as "und".'}]},{id:"conj-danach",category:"conjunction",de:"danach",en:["after that","afterwards"],hi:["उसके बाद"],hiTranslit:"uske baad",ipa:"daˈnaːx",deva:"डनाख़्",level:"A2",theme:"time",illustration:"conj-danach",type:"adverbial",verbPosition:"inversion",notes:'A slightly more formal "then" than "dann" — same rule: it fills position 1, so the verb comes immediately after it, before the subject.',examples:[{de:[{t:"Ich dusche",g:0},{t:","},{t:"danach",g:1},{t:"frühstücke",g:2},{t:"ich",g:3}],en:[{t:"I shower",g:0},{t:","},{t:"after that",g:1},{t:"I",g:3},{t:"have breakfast",g:2}],hi:[{t:"मैं नहाता हूँ",g:0},{t:","},{t:"उसके बाद",g:1},{t:"मैं",g:3},{t:"नाश्ता करता हूँ",g:2}],hiTranslit:"main nahaata hoon, uske baad main naashta karta hoon",note:'"danach" fills position 1, so "frühstücke" follows immediately, before "ich" — the same inversion as its shorter synonym "dann".'}]},{id:"conj-jedoch",category:"conjunction",de:"jedoch",en:["however"],hi:["फिर भी","लेकिन"],hiTranslit:"phir bhi / lekin",ipa:"jeˈdɔx",deva:"येडॉख़्",level:"B1",theme:"logic",illustration:"conj-jedoch",type:"adverbial",verbPosition:"inversion",notes:'A more formal "however" that many learners mistake for "aber" — but unlike "aber", jedoch occupies position 1 and forces the verb before the subject.',examples:[{de:[{t:"Das Essen war teuer",g:0},{t:","},{t:"jedoch",g:1},{t:"schmeckte",g:2},{t:"es",g:3},{t:"hervorragend",g:4}],en:[{t:"The food was expensive",g:0},{t:","},{t:"however",g:1},{t:"it",g:3},{t:"tasted",g:2},{t:"excellent",g:4}],hi:[{t:"खाना महँगा था",g:0},{t:","},{t:"फिर भी",g:1},{t:"उसका स्वाद",g:3},{t:"शानदार",g:4},{t:"था",g:2}],hiTranslit:"khaana mehnga tha, phir bhi uska swaad shaandaar tha",note:'"jedoch" fills position 1, so "schmeckte" follows immediately, before "es" — unlike "aber", which would leave the verb untouched in position 2.'}]},{id:"conj-allerdings",category:"conjunction",de:"allerdings",en:["however","though"],hi:["हालांकि"],hiTranslit:"haalaanki",ipa:"ˈalɐdɪŋs",deva:"अलडिंग्स्",level:"B1",theme:"logic",illustration:"conj-allerdings",type:"adverbial",verbPosition:"inversion",notes:'A qualifying "however, mind you" often added almost as an afterthought — but it still fills position 1 like every connector here, so the verb must follow it directly, not the subject.',examples:[{de:[{t:"Das Auto ist schnell",g:0},{t:","},{t:"allerdings",g:1},{t:"verbraucht",g:2},{t:"es",g:3},{t:"viel Benzin",g:4}],en:[{t:"The car is fast",g:0},{t:","},{t:"however",g:1},{t:"it",g:3},{t:"uses",g:2},{t:"a lot of petrol",g:4}],hi:[{t:"गाड़ी तेज़ है",g:0},{t:","},{t:"हालांकि",g:1},{t:"यह",g:3},{t:"बहुत पेट्रोल",g:4},{t:"खर्च करती है",g:2}],hiTranslit:"gaadi tez hai, haalaanki yah bahut petrol kharch karti hai",note:'"allerdings" occupies position 1, so "verbraucht" comes right after it, before "es" — inversion, not the untouched verb-second order a coordinator like "aber" would leave.'}]},{id:"conj-sonst",category:"conjunction",de:"sonst",en:["otherwise"],hi:["वरना"],hiTranslit:"varna",ipa:"zɔnst",deva:"ज़ॉन्स्ट्",level:"A2",theme:"logic",illustration:"conj-sonst",type:"adverbial",verbPosition:"inversion",notes:"Warns of a consequence if something is not done — grammatically identical to the other connectors in this set: position 1, verb immediately after, subject after that.",examples:[{de:[{t:"Beeil dich",g:0},{t:","},{t:"sonst",g:1},{t:"verpassen",g:2},{t:"wir",g:3},{t:"den Bus",g:4}],en:[{t:"Hurry up",g:0},{t:","},{t:"otherwise",g:1},{t:"we",g:3},{t:"will miss",g:2},{t:"the bus",g:4}],hi:[{t:"जल्दी करो",g:0},{t:","},{t:"वरना",g:1},{t:"हम",g:3},{t:"बस से",g:4},{t:"चूक जाएंगे",g:2}],hiTranslit:"jaldi karo, varna hum bus se chook jaayenge",note:'"sonst" fills position 1, so "verpassen" comes right after it, before "wir" — inversion, exactly like every other connector in this set.'}]},{id:"conj-stattdessen",category:"conjunction",de:"stattdessen",en:["instead"],hi:["इसके बजाय"],hiTranslit:"iske bajaay",ipa:"ʃtatˈdɛsn̩",deva:"श्टट्डेसन्",level:"B1",theme:"logic",illustration:"conj-stattdessen",type:"adverbial",verbPosition:"inversion",notes:"Offers a substitute action or thing — same inversion rule as the rest of this set: position 1, verb immediately after, subject after that.",examples:[{de:[{t:"Ich koche nicht",g:0},{t:","},{t:"stattdessen",g:1},{t:"bestellen",g:2},{t:"wir",g:3},{t:"Pizza",g:4}],en:[{t:"I am not cooking",g:0},{t:","},{t:"instead",g:1},{t:"we",g:3},{t:"are ordering",g:2},{t:"pizza",g:4}],hi:[{t:"मैं खाना नहीं बनाऊँगा",g:0},{t:","},{t:"इसके बजाय",g:1},{t:"हम",g:3},{t:"पिज़्ज़ा",g:4},{t:"मंगाएंगे",g:2}],hiTranslit:"main khaana nahin banaunga, iske bajaay hum pizza mangaayenge",note:'"stattdessen" occupies position 1, so "bestellen" comes right after it, before "wir" — the same inversion as every connector here.'}]},{id:"conj-immerhin",category:"conjunction",de:"immerhin",en:["at least","after all"],hi:["फिर भी","कम से कम"],hiTranslit:"phir bhi / kam se kam",ipa:"ˈɪmɐhɪn",deva:"इमहिन्",level:"B1",theme:"logic",illustration:"conj-immerhin",type:"adverbial",verbPosition:"inversion",notes:"Softens a complaint by pointing to a silver lining — grammatically still an adverbial connector: position 1, so the verb comes right after it, before the subject.",examples:[{de:[{t:"Der Zug hatte Verspätung",g:0},{t:","},{t:"immerhin",g:1},{t:"hatten",g:2},{t:"wir",g:3},{t:"einen Sitzplatz",g:4}],en:[{t:"The train was late",g:0},{t:","},{t:"at least",g:1},{t:"we",g:3},{t:"had",g:2},{t:"a seat",g:4}],hi:[{t:"ट्रेन देर से आई",g:0},{t:","},{t:"फिर भी",g:1},{t:"हमें",g:3},{t:"एक सीट",g:4},{t:"मिली",g:2}],hiTranslit:"train der se aayi, phir bhi hamein ek seat mili",note:'"immerhin" fills position 1, so "hatten" comes right after it, before "wir" — inversion, the same pattern as every connector in this set.'}]},{id:"conj-andernfalls",category:"conjunction",de:"andernfalls",en:["otherwise"],hi:["अन्यथा"],hiTranslit:"anyatha",ipa:"ˈandɐnfals",deva:"अन्डन्फ़ल्स्",level:"B1",theme:"logic",illustration:"conj-andernfalls",type:"adverbial",verbPosition:"inversion",notes:'A more formal synonym of "sonst" — same inversion rule: the verb must come immediately after it, before the subject, not the other way around.',examples:[{de:[{t:"Wir müssen uns beeilen",g:0},{t:","},{t:"andernfalls",g:1},{t:"verpassen",g:2},{t:"wir",g:3},{t:"den Zug",g:4}],en:[{t:"We must hurry",g:0},{t:","},{t:"otherwise",g:1},{t:"we",g:3},{t:"will miss",g:2},{t:"the train",g:4}],hi:[{t:"हमें जल्दी करनी होगी",g:0},{t:","},{t:"अन्यथा",g:1},{t:"हम",g:3},{t:"ट्रेन से",g:4},{t:"चूक जाएंगे",g:2}],hiTranslit:"hamein jaldi karni hogi, anyatha hum train se chook jaayenge",note:'"andernfalls" occupies position 1, so "verpassen" comes right after it, before "wir" — the same inversion as its everyday synonym "sonst".'}]},{id:"conj-inzwischen",category:"conjunction",de:"inzwischen",en:["meanwhile","in the meantime"],hi:["इस बीच"],hiTranslit:"is beech",ipa:"ɪnˈtsvɪʃn̩",deva:"इन्त्स्विश्न्",level:"B1",theme:"time",illustration:"conj-inzwischen",type:"adverbial",verbPosition:"inversion",notes:"Marks something happening at the same time as something else — same inversion rule as every connector here: position 1, verb immediately after, subject after that.",examples:[{de:[{t:"Ich koche das Abendessen",g:0},{t:","},{t:"inzwischen",g:1},{t:"deckt",g:2},{t:"sie",g:3},{t:"den Tisch",g:4}],en:[{t:"I am cooking dinner",g:0},{t:","},{t:"meanwhile",g:1},{t:"she",g:3},{t:"is setting",g:2},{t:"the table",g:4}],hi:[{t:"मैं रात का खाना बना रहा हूँ",g:0},{t:","},{t:"इस बीच",g:1},{t:"वह",g:3},{t:"मेज़",g:4},{t:"लगा रही है",g:2}],hiTranslit:"main raat ka khaana bana raha hoon, is beech vah mez laga rahi hai",note:'"inzwischen" fills position 1, so "deckt" comes right after it, before "sie" — inversion, the same pattern every connector in this set follows.'}]},{id:"conj-ansonsten",category:"conjunction",de:"ansonsten",en:["otherwise","apart from that"],hi:["अन्यथा","वरना"],hiTranslit:"anyatha / varna",ipa:"anˈzɔnstn̩",deva:"अन्ज़ॉन्स्टन्",level:"B1",theme:"logic",illustration:"conj-ansonsten",type:"adverbial",verbPosition:"inversion",notes:'A slightly softer, more conversational synonym of "sonst" — same inversion rule: the verb must come immediately after it, before the subject.',examples:[{de:[{t:"Das Zimmer ist klein",g:0},{t:","},{t:"ansonsten",g:1},{t:"ist",g:2},{t:"alles",g:3},{t:"gut",g:4}],en:[{t:"The room is small",g:0},{t:","},{t:"otherwise",g:1},{t:"everything",g:3},{t:"is",g:2},{t:"good",g:4}],hi:[{t:"कमरा छोटा है",g:0},{t:","},{t:"अन्यथा",g:1},{t:"सब कुछ",g:3},{t:"अच्छा",g:4},{t:"है",g:2}],hiTranslit:"kamra chota hai, anyatha sab kuch achcha hai",note:'"ansonsten" fills position 1 just like "sonst", so "ist" must come right after it, before "alles" rather than after.'}]}];export{e as conjunctions};
